"""Convert a jupytext percent-format .py into .ipynb (no jupytext needed).
Usage: py2nb.py src.py dst.ipynb [--colab]
--colab: add an 'Open in Colab' badge and a setup cell that fetches rotary_model.py."""
import re, sys, nbformat
from nbformat.v4 import new_notebook, new_code_cell, new_markdown_cell

src, dst = sys.argv[1], sys.argv[2]
colab = "--colab" in sys.argv
lines = open(src, encoding="utf-8").read().splitlines()
if lines and lines[0].strip() == "# ---":
    lines = lines[lines.index("# ---", 1) + 1:]

cells, kind, buf = [], None, []


def flush():
    if kind is None:
        return
    while buf and not buf[-1].strip(): buf.pop()
    while buf and not buf[0].strip(): buf.pop(0)
    if kind == "md":
        cells.append(new_markdown_cell("\n".join(re.sub(r"^# ?", "", l) if l.startswith("#") else l for l in buf)))
    else:
        cells.append(new_code_cell("\n".join(buf)))


for l in lines:
    if l.startswith("# %%"):
        flush(); buf = []
        kind = "md" if "[markdown]" in l else "code"
    else:
        buf.append(l)
flush()

meta = {"kernelspec": {"display_name": "Python 3", "language": "python", "name": "python3"},
        "language_info": {"name": "python"}}
if colab:
    repo = "jooyongsim/Pendulum_control"
    nb_path = "simulator/" + dst.replace("\\", "/").split("/")[-1]
    badge = (f"[![Open In Colab](https://colab.research.google.com/assets/colab-badge.svg)]"
             f"(https://colab.research.google.com/github/{repo}/blob/main/{nb_path})\n\n")
    cells[0].source = badge + cells[0].source
    meta["colab"] = {"provenance": [], "toc_visible": True}
    meta["accelerator"] = "GPU"
nb = new_notebook(cells=cells, metadata=meta)
nbformat.validate(nb)
nbformat.write(nb, dst)
print(f"{dst}: {len(cells)} cells ({sum(c.cell_type == 'markdown' for c in cells)} markdown, "
      f"{sum(c.cell_type == 'code' for c in cells)} code)")

